package com.shiftnest.attendance;
import android.os.Bundle;
import android.widget.*;
import com.google.android.gms.maps.*;
import com.google.android.gms.maps.model.*;
import com.google.firebase.firestore.*;
import java.util.*;
public class AdminLocationTrackingActivity extends ShiftNestBaseActivity implements OnMapReadyCallback {
    private final List<DocumentSnapshot> employees=new ArrayList<>(),visible=new ArrayList<>();private final Map<String,DocumentSnapshot> locations=new HashMap<>();private Spinner filter;private LinearLayout table;private TextView summary,detail;private GoogleMap map;private ListenerRegistration changes;private Button release;private boolean releasing;private String selected="",liveError="",employeeError="";private int employeeGeneration;private final android.os.Handler timer=new android.os.Handler(android.os.Looper.getMainLooper());private final Runnable staleRefresh=new Runnable(){public void run(){render();timer.postDelayed(this,60000);}};
    @Override protected void onCreate(Bundle s){super.onCreate(s);if(isFinishing())return;page("Location Tracking");filter=departments(this::render);summary=text("Loading employees…",16);screen.addView(summary);screen.addView(button("Refresh locations",()->{loadEmployees();watchLocations();}));table=new LinearLayout(this);table.setOrientation(1);screen.addView(table);detail=text("Tap an employee row to inspect their location.",16);screen.addView(detail);release=button("Company approval: unblock selected employee",this::releaseSelected);release.setEnabled(false);screen.addView(release);if(!BuildConfig.DEMO_BACKEND){FrameLayout container=new FrameLayout(this);container.setId(R.id.trackingMapHost);screen.addView(container,new LinearLayout.LayoutParams(-1,dp(280)));SupportMapFragment fragment=(SupportMapFragment)getSupportFragmentManager().findFragmentByTag("tracking_map");if(fragment==null){fragment=SupportMapFragment.newInstance();getSupportFragmentManager().beginTransaction().replace(container.getId(),fragment,"tracking_map").commit();}fragment.getMapAsync(this);}else screen.addView(text("Demo: map tiles disabled. GPS coordinates, radius checks and location tables still work.",15));loadEmployees();}
    @Override protected void onStart(){super.onStart();watchLocations();timer.post(staleRefresh);}
    private void watchLocations(){if(changes!=null)changes.remove();liveError="";changes=FirebaseFirestore.getInstance().collection("latestLocations").addSnapshotListener((q,e)->{if(e!=null){liveError=backendError("Load live tracking",e)+". Tap Refresh locations.";render();return;}liveError="";locations.clear();if(q!=null)for(DocumentSnapshot d:q)locations.put(d.getId(),d);render();});}
    @Override protected void onStop(){if(changes!=null)changes.remove();timer.removeCallbacks(staleRefresh);super.onStop();}
    private void loadEmployees(){final int run=++employeeGeneration;employeeError="";summary.setText("Loading employees...");ShiftNestRequests.read(FirebaseFirestore.getInstance().collection("employees").whereEqualTo("active",true).get()).addOnSuccessListener(q->{if(run!=employeeGeneration||isFinishing()||isDestroyed())return;employeeError="";employees.clear();employees.addAll(q.getDocuments());employees.sort(Comparator.comparing(d->ShiftNestData.string(d,"name")));render();}).addOnFailureListener(e->{if(run!=employeeGeneration||isFinishing()||isDestroyed())return;employeeError=backendError("Load tracking employees",e)+". Tap Refresh locations.";render();});}
    private void render(){if(table==null||filter==null)return;List<String[]>rows=new ArrayList<>();visible.clear();String dep=String.valueOf(filter.getSelectedItem());int outside=0;for(DocumentSnapshot e:employees){String department=ShiftNestData.department(ShiftNestData.string(e,"role"));if(!dep.equals("All Employees")&&!dep.equals(department))continue;DocumentSnapshot loc=locations.get(e.getId());String st=Boolean.TRUE.equals(e.getBoolean("attendanceBlocked"))?"BLOCKED: FAKE GPS":loc!=null&&"fixed".equals(ShiftNestData.string(e,"workLocationType"))&&!ShiftNestData.string(e,"locationId").equals(ShiftNestData.string(loc,"locationId"))?"Assignment changed; awaiting GPS":ShiftNestData.locationStatus(loc);if(st.equals("OUTSIDE LOCATION"))outside++;Date date=loc==null?null:ShiftNestData.timestamp(loc,"timestamp");visible.add(e);rows.add(new String[]{ShiftNestData.string(e,"name"),department,ShiftNestData.string(e,"locationName"),st,date==null?"--":ShiftNestData.format(date,"MM-dd HH:mm:ss")});}summary.setText("Employees: "+visible.size()+" • Outside: "+outside+"\nRed = outside assigned radius. GPS older than 5 minutes is marked stale."+(liveError.isEmpty()?"":"\n"+liveError)+(employeeError.isEmpty()?"":"\n"+employeeError));table.removeAllViews();table.addView(ShiftNestTable.create(this,new String[]{"Employee","Department","Assigned site","Location status","Last updated"},rows,i->select(visible.get(i))));if(!selected.isEmpty())display(selected);}
    private void select(DocumentSnapshot e){selected=e.getId();display(selected);if(locations.containsKey(selected)){display(selected);return;}final String id=selected;detail.setText("Loading previous location…");ShiftNestRequests.read(FirebaseFirestore.getInstance().collection("locationLogs").whereEqualTo("employeeId",id).orderBy("timestamp",Query.Direction.DESCENDING).limit(1).get()).addOnSuccessListener(q->{if(!q.isEmpty())locations.put(id,q.getDocuments().get(0));if(selected.equals(id))display(id);}).addOnFailureListener(error->{if(selected.equals(id))detail.setText(backendError("Load location",error));});}
    private void display(String id){DocumentSnapshot e=null;for(DocumentSnapshot employee:employees)if(employee.getId().equals(id))e=employee;DocumentSnapshot d=locations.get(id);if(e==null)return;release.setEnabled(!releasing&&Boolean.TRUE.equals(e.getBoolean("attendanceBlocked")));String name=ShiftNestData.string(e,"name");String status=d!=null&&"fixed".equals(ShiftNestData.string(e,"workLocationType"))&&!ShiftNestData.string(e,"locationId").equals(ShiftNestData.string(d,"locationId"))?"Assignment changed; awaiting GPS":ShiftNestData.locationStatus(d);detail.setText(name+(Boolean.TRUE.equals(e.getBoolean("attendanceBlocked"))?"\nATTENDANCE BLOCKED: fake GPS report. Company approval required.":"")+"\n"+status+(d==null?"":"\nLatitude: "+ShiftNestData.string(d,"latitude")+"\nLongitude: "+ShiftNestData.string(d,"longitude")));detail.setTextColor((Boolean.TRUE.equals(e.getBoolean("attendanceBlocked"))||status.equals("OUTSIDE LOCATION"))?0xFFF05454:color(R.color.shiftnest_text));if(map!=null){map.clear();if(d!=null&&d.get("latitude") instanceof Number&&d.get("longitude") instanceof Number){LatLng point=new LatLng(((Number)d.get("latitude")).doubleValue(),((Number)d.get("longitude")).doubleValue());float hue=status.equals("OUTSIDE LOCATION")?BitmapDescriptorFactory.HUE_RED:status.equals("Inside location")?BitmapDescriptorFactory.HUE_GREEN:BitmapDescriptorFactory.HUE_ORANGE;map.addMarker(new MarkerOptions().position(point).title(name).snippet(status).icon(BitmapDescriptorFactory.defaultMarker(hue)));map.moveCamera(CameraUpdateFactory.newLatLngZoom(point,15));}}}
    private void releaseSelected(){
        if(releasing||selected.isEmpty()){problem("Select a blocked employee first.");return;}
        final String id=selected;
        EditText note=new EditText(this);note.setHint("Company approval / unblock reason");note.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);styleEditable(note);
        note.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(500)});
        androidx.appcompat.app.AlertDialog dialog=ShiftNestLanguage.dialog(this)
            .setTitle("Unblock attendance with company approval")
            .setMessage("Only approve after reviewing the fake GPS report. The employee must still turn off mock GPS. New fake readings will block attendance again.")
            .setView(note).setNegativeButton("Cancel",null).setPositiveButton("Approve unblock",null).create();
        dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{
            String reason=note.getText().toString().trim();if(reason.length()<3){note.setError("Enter an approval reason (at least 3 characters).");return;}
            if(!requireOnline("Unblock employee attendance"))return;
            releasing=true;release.setEnabled(false);dialog.getButton(-1).setEnabled(false);dialog.getButton(-2).setEnabled(false);note.setEnabled(false);dialog.setCancelable(false);
            Map<String,Object> data=new HashMap<>();data.put("employeeId",id);data.put("note",reason);
            ShiftNestRequests.write(com.google.firebase.functions.FirebaseFunctions.getInstance("asia-south1").getHttpsCallable("releaseAttendanceBlock").call(data))
                .addOnSuccessListener(result->{releasing=false;dialog.dismiss();success("Attendance is unblocked. The employee must use real GPS.");loadEmployees();})
                .addOnFailureListener(error->{releasing=false;dialog.getButton(-1).setEnabled(true);dialog.getButton(-2).setEnabled(true);note.setEnabled(true);dialog.setCancelable(true);release.setEnabled(true);problem(backendError("Unblock attendance",error));});
        }));dialog.show();
    }
    @Override public void onMapReady(GoogleMap g){map=g;g.getUiSettings().setZoomControlsEnabled(true);if(!selected.isEmpty())display(selected);}
}
